<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT o.*,o.reference AS code,o.date_promise AS date_prevue,o.depose_par AS user_id,c.nom,c.prenom,c.telephone,c.email FROM commandes o JOIN clients c ON c.id=o.client_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Commande introuvable');}$page_title='Détail '.$o['code'];$s=db()->prepare("SELECT l.*,l.sous_total AS subtotal,s.nom AS service FROM commande_lignes l JOIN tarifs t ON t.id=l.tarif_id JOIN services s ON s.id=t.service_id WHERE l.commande_id=?");$s->execute([$id]);$items=$s->fetchAll();$s=db()->prepare("SELECT COALESCE(SUM(montant),0) FROM paiements WHERE commande_id=?");$s->execute([$id]);$paid=(float)$s->fetchColumn();$balance=(float)$o['total']-$paid;$payModes=['especes'=>'Espèces','mtn_momo'=>'MTN Mobile Money','orange_money'=>'Orange Money','virement'=>'Virement','carte'=>'Carte'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['pay'])){$amount=(float)$_POST['montant'];if($amount>0&&$amount<=$balance){try{db()->prepare("INSERT INTO paiements(commande_id,montant,mode,reference) VALUES(?,?,?,?)")->execute([$id,$amount,$_POST['mode'],trim($_POST['reference'])]);flash('Paiement enregistré.');}catch(Throwable $e){flash('Paiement refusé : vérifiez le montant.','error');}}else flash('Paiement refusé : vérifiez le montant.','error');}if(isset($_POST['retire'])){if($o['statut']==='pret' && $balance<=0){try{db()->prepare("UPDATE commandes SET statut='retire' WHERE id=?")->execute([$id]);flash('Retrait confirmé.');}catch(Throwable $e){flash($e->getMessage(),'error');}}else{flash('La commande doit être prête et entièrement payée avant le retrait.','error');}}redirect('order_view.php?id='.$id);}
require 'includes/header.php';?>
<div class="cards"><div class="stat"><div class="label">Montant total</div><strong><?=money($o['total'])?></strong></div><div class="stat"><div class="label">Déjà payé</div><strong><?=money($paid)?></strong></div><div class="stat"><div class="label">Reste à payer</div><strong><?=money($balance)?></strong></div><div class="stat"><div class="label">Statut</div><strong style="font-size:20px"><?=e(status_label($o['statut']))?></strong></div></div>
<div class="panel"><div class="panel-head"><h2><?=e($o['code'])?> · <?=e($o['prenom'].' '.$o['nom'])?></h2><a class="btn light" href="invoice_print.php?id=<?=$id?>" target="_blank">Imprimer reçu</a></div><p>Téléphone : <b><?=e($o['telephone'])?></b> · Dépôt <?=e($o['type_depot'])?> · Retrait prévu : <?=e($o['date_prevue'])?></p><div class="table-wrap"><table><thead><tr><th>Prestation / vêtement</th><th>Quantité</th><th>Prix unitaire</th><th>Sous-total</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['service'])?> <small>(<?=e($it['description'])?>)</small></td><td><?=$it['quantite']?></td><td><?=money($it['prix_unitaire'])?></td><td><?=money($it['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if(can_manage() && $o['statut']==='pret'):?><div class="panel"><h2>Retrait client</h2><?php if($balance<=0):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn green" name="retire" value="1" data-confirm="Confirmer la remise des vêtements au client ?">Confirmer le retrait</button></form><?php else:?><p class="notice">Le retrait sera disponible après règlement du solde de <?=money($balance)?>.</p><?php endif;?></div><?php endif;?>
<?php if(can_manage()&&$balance>0):?><div class="panel"><h2>Enregistrer un paiement</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="pay" value="1"><div class="field"><label>Montant (FCFA)</label><input type="number" step="1" min="1" max="<?=$balance?>" name="montant" required></div><div class="field"><label>Mode de paiement</label><select name="mode"><?php foreach($payModes as $k=>$v):?><option value="<?=$k?>"><?=$v?></option><?php endforeach;?></select></div><div class="field full"><label>Référence (facultatif)</label><input name="reference"></div><div><button class="btn green">Valider le paiement</button></div></form></div><?php endif;?>
<div class="panel"><h2>Informer le client par SMS</h2><p>Un message simple est préparé dans l'application SMS du téléphone, sans WhatsApp.</p><?php $msg=($o['statut']==='pret'?'Bonjour '.$o['prenom'].', votre linge est prêt à être retiré. ':'Bonjour '.$o['prenom'].', votre commande est actuellement : '.status_label($o['statut']).'. ').'Référence : '.$o['code'].'. Montant total : '.money($o['total']).'. Reste à payer : '.money(max(0,$balance)).'. Merci pour votre confiance !'; $smsPhone=preg_replace('/\D/','',$o['telephone']);if(strlen($smsPhone)===9)$smsPhone='237'.$smsPhone; ?><a class="btn green" href="sms:+<?=e($smsPhone)?>?body=<?=rawurlencode($msg)?>">Ouvrir les SMS et envoyer</a><small>L'application SMS du téléphone s'ouvre avec le numéro et le texte. L'employé appuie sur Envoyer. Un téléphone ou modem SMS configuré est nécessaire.</small></div>
<?php require 'includes/footer.php';?>
